def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    opp_bids = []
    strong_bids = []
    desperate_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                opp_bids.append(bid)
                if bid <= 110:
                    strong_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, 18.0))

    slots = supply / float(WATER_REQ)
    tight = slots < 2.0
    medium = slots < 2.5

    prev_high = max(opp_bids) if opp_bids else 0.0
    prev_mid_high = max(strong_bids) if strong_bids else 0.0

    my_prev_bid = None
    my_prev_won = None
    sample_prev = None
    for opp in alive:
        p = opp.get('previous_trace', {})
        if p:
            sample_prev = p
            break
    if sample_prev and sample_prev.get('day') is not None and sample_prev.get('day') >= 1:
        my_prev_bid = budget - DAILY_SALARY
        if my_prev_bid < 0:
            my_prev_bid = 0.0
        if no_water == 0:
            my_prev_won = True
        elif no_water >= 1:
            my_prev_won = False

    urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if critical:
        target = max(95.0, prev_mid_high + 3.0)
        if prev_high >= 140:
            target = max(target, 98.0)
        return max(0.0, min(budget, target))

    if tight:
        if urgent:
            target = max(90.0, prev_mid_high + 2.5)
        else:
            if desperate_count >= 2:
                target = max(72.0, prev_mid_high + 1.5)
            else:
                target = max(68.0, prev_mid_high + 1.0)
        if prev_high >= 150 and hp > 3:
            target = min(target, 84.0)
        return max(0.0, min(budget, target))

    if medium:
        if my_prev_won is False:
            target = max(60.0, prev_mid_high + 1.0)
        elif urgent:
            target = max(58.0, prev_mid_high)
        else:
            target = 46.0 if prev_high >= 140 else 52.0
        return max(0.0, min(budget, target))

    if urgent:
        target = 55.0
    else:
        target = 32.0 if prev_high >= 140 else 38.0
    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    # Read yesterday's behavior from previous_trace (immediate reaction only)
    prev_bids = []
    prev_by_id = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bid_f = float(bid)
            except Exception:
                continue
            prev_bids.append(bid_f)
            prev_by_id[oid] = bid_f

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Identify Cindy if present
    cindy_bid = prev_by_id.get('Cindy', None)

    # Supply pressure: when supply is tight, bids must be more competitive.
    tightness = 0.0
    if supply <= WATER_REQ:
        tightness = 1.0
    elif supply <= 0.75 * 25:
        tightness = 0.6
    else:
        tightness = 0.3

    # Base bid aims to secure water for a 10-day horizon without overpaying.
    # If Cindy was aggressive yesterday, we anticipate continued competition.
    if highest_prev_bid >= DAILY_SALARY * 1.6:  # ~144
        # Cindy-like pressure: bid to avoid being outcompeted.
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * (0.85 + 0.15 * tightness)
        else:
            target = DAILY_SALARY * (0.55 + 0.25 * tightness)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:  # ~81
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * (0.75 + 0.1 * tightness)
        else:
            target = DAILY_SALARY * (0.5 + 0.2 * tightness)
    else:
        # Opponents not bidding hard; conserve budget.
        if hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * (0.7 + 0.1 * tightness)
        else:
            target = DAILY_SALARY * (0.45 + 0.15 * tightness)

    # If Cindy specifically bid extremely high yesterday, slightly overbid her baseline.
    if cindy_bid is not None and cindy_bid >= DAILY_SALARY * 1.7:
        target = max(target, cindy_bid * 0.92)

    # Budget safety: never exceed budget.
    # Also keep a minimum bid floor to stay in contention.
    min_floor = 0.0
    if hp <= 2.0 or no_water_days >= 2:
        min_floor = DAILY_SALARY * 0.6
    else:
        min_floor = DAILY_SALARY * 0.35

    bid = max(min_floor, target)
    bid = min(bid, budget)

    # Clamp to non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = avg_bid * 1.05
    else:
        target_bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    return min(my_status['budget'], max(target_bid, DAILY_SALARY * 0.4))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in opponents_status.values():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and isinstance(prev, dict) and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    # Determine target bid based on my HP and yesterday's pressure
    if my_status['hp'] <= 2:
        # Critical: need water no matter what
        if yesterday_bids:
            target = max(yesterday_bids) + 2.0
        else:
            target = DAILY_SALARY * 0.9
        return min(my_status['budget'], max(target, 10.0))
    elif my_status['hp'] <= 5:
        # Moderate need, bid competitively
        if yesterday_bids:
            target = max(yesterday_bids) - 1.0
            if target < 10:
                target = max(yesterday_bids) + 0.5
        else:
            target = DAILY_SALARY * 0.6
        return min(my_status['budget'], max(target, 5.0))
    else:
        # Healthy, conserve budget
        if yesterday_bids:
            # Use median to undercut if possible
            sorted_bids = sorted(yesterday_bids)
            median_idx = len(sorted_bids) // 2
            median_bid = sorted_bids[median_idx]
            target = median_bid * 0.8
        else:
            target = DAILY_SALARY * 0.4
        return min(my_status['budget'], max(target, 2.0))
